// FortreeCity_Gym (zone 119): generated by converter/gen_interiors.py from Sapphire's simple people and signs.
// Messages: src/text/script/0138_room_FortreeCity_Gym.txt
#include "asm/field_script.inc"
#include "hoenn.h"  // ch7
#include "hoenn_trainers.h"  // ch7
#include "hoenn_story.inc"  // ch7

    ScriptEntry Script_None
    ScriptEntry FG_Winona  // 2: FortreeCity_Gym_EventScript_Winona  // story:
    ScriptEntry FG_GymGuide  // 3: FortreeCity_Gym_EventScript_GymGuide  // story:
    ScriptEntry FG_GymStatue  // 4: FortreeCity_Gym_EventScript_LeftGymStatue / RightGymStatue  // story:
    ScriptEntriesEnd

Script_None:
    VMHalt
    .balign 4, 0

// ---- story (chapter Ch7, ch7 agent 2026-10-07; Sapphire data/maps/FortreeCity_Gym/scripts.inc; generators must keep
// everything from this line on; entries above marked "// story:")
// Scripts 2-4, text lines 1-9 (line 0 is the generator's). Winona (uid 1), the Gym guide (uid 6), the two statue plaques
// ((1,21), (4,21); script 4) and the four trainers (Jared uid 2, Terrell 3, Kylee 4, Will 5: Black 2's eye-contact
// trainer script 3000 + id) are in data/story/ch7.json. Room tiles = Sapphire tiles + (1,1).
// Not ported: the rotating gates (FortreeCity_Gym_OnTransition / OnWarp: RotatingGate_InitPuzzle*): the room builder
// leaves them out (b2tools/gyms_league_rooms.py), so there is nothing to turn.
#define T_ReceivedFeatherBadge 1
#define T_ExplainFeatherBadge 2
#define T_ExplainAerialAce 3
#define T_WinonaPostBattle 4
#define T_GuideAdvice 5
#define T_GuidePostVictory 6
#define T_Statue 7
#define T_StatueCertified 8
#define T_BagFull 9
#define FG_WINONA 1

FG_Winona:                          // trainerbattle_single TRAINER_WINONA, ..., WinonaDefeated, NO_MUSIC
    h_lock
#ifdef HOENN_TEST_CH7
    PokePartyRecoverAll             // TEST ONLY: a full heal (PP too) for the Gym battle
#endif
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_defeated TRAINER_WINONA, L_FG_WinonaAgain
    TrainerSayMessage TRAINER_WINONA, 0, FG_WINONA   // I am Winona. I am the Leader of the Fortree Pokémon Gym. ...
    ActorMsgClose                   // (NO_MUSIC: no eye-contact music)
    h_trainerbattle TRAINER_WINONA  // (in battle: "Never before have I seen a Trainer command Pokémon with more grace ...")
    h_buffer_player                 // FortreeCity_Gym_EventScript_WinonaDefeated
    SystemMsg T_ReceivedFeatherBadge, 2 // <player> received the Feather Badge from Winona.
    h_badge_fanfare                 // Common_EventScript_PlayGymBadgeFanfare
    MsgWinCloseAll
    h_msgbox_actor T_ExplainFeatherBadge, FG_WINONA   // With the Feather Badge, all Pokémon up to Lv 70 ... take this ...
    h_closemessage
    h_setflag FLAG_DEFEATED_FORTREE_GYM
    h_givebadge 6                   // setflag FLAG_BADGE06_GET
    h_set_gym_trainers 6            // Jared, Terrell, Kylee and Will count as beaten
L_FG_GiveAerialAce:                 // FortreeCity_Gym_EventScript_GiveAerialAce2
    h_giveitem ITEM_TM40            // TM40 is Aerial Ace in Black 2 too
    h_goto_if_eq HLIB_RESULT, 0, L_FG_BagFull
    h_msgbox_actor T_ExplainAerialAce, FG_WINONA   // TM40 contains Aerial Ace. Its speed... No Pokémon should be able to avoid it.
    h_setflag FLAG_RECEIVED_TM_AERIAL_ACE
    h_release
L_FG_WinonaAgain:
    h_goto_if_unset FLAG_RECEIVED_TM_AERIAL_ACE, L_FG_GiveAerialAce
    h_msgbox T_WinonaPostBattle     // Though I fell to you, I will remain devoted to Bird Pokémon.
    h_release
L_FG_BagFull:                       // Common_EventScript_ShowBagIsFull
    h_bag_is_full T_BagFull
    h_release

FG_GymGuide:                        // FortreeCity_Gym_EventScript_GymGuide
    h_lock
#if HOENN_TEST_CH7 >= 3             // TEST ONLY (HOENN_TEST_CH7=3): the guide warps to the tile below Winona (a real warp inside the zone)
    VMCall Test_Ch7Start                // (story_finish: the test party, also when the sign test warp lands in the Gym)
    h_warp_arrive 119, 4, 3, 0          // (story_finish: the arrival script 10017, so Winona answers afterwards)
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt
#endif
    h_buffer_player
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_DEFEATED_FORTREE_GYM, L_FG_GuidePostVictory
    h_msgbox T_GuideAdvice          // Yo, how's it going, Champion-bound <player>? ...
    h_release
L_FG_GuidePostVictory:
    h_msgbox T_GuidePostVictory     // You did it! You've achieved liftoff!
    h_release

FG_GymStatue:                       // (lockall; MSGBOX_DEFAULT)
    h_lock
#if HOENN_TEST_CH7 >= 3             // TEST ONLY (HOENN_TEST_CH7=3): the statue warps to Route 120's bridge, east of Steven
    VMCall Test_Ch7Start
    h_warp_arrive 474, 422, 75, 2, 2    // (the bridge is at height 32; arrival script 10017: Steven answers)
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt
#endif
    SEPlay SEQ_SE_MESSAGE
    h_goto_if_badge 6, L_FG_StatueCertified
    MsgPlaceSign T_Statue, 2        // Fortree City Pokémon Gym (a signboard window, as Sapphire's sign-like statue)
    MsgPlaceSignClose
    h_release
L_FG_StatueCertified:
    h_buffer_player
    MsgPlaceSign T_StatueCertified, 2   // Fortree City Pokémon Gym / Winona's Certified Trainers: <player>
    MsgPlaceSignClose
    h_release
    .balign 4, 0

#ifdef HOENN_TEST_CH7
#include "scenes/ch7_test.inc"     // Test_Ch7Start (test builds only)
#endif
